BEGIN TRAN;
IF EXISTS (SELECT 1 FROM users WHERE email = @email OR phone_number = @phone_number)
BEGIN ROLLBACK; THROW 50001, N'Email hoặc số điện thoại đã tồn tại', 1; END;

INSERT INTO users (email, phone_number, password_hash, full_name)
VALUES (@email, @phone_number, @password_hash, @full_name);

DECLARE @new_user_id INT = SCOPE_IDENTITY();

INSERT INTO user_verifications (user_id, [type], code, expires_at)
VALUES (@new_user_id, 'EMAIL', @code, DATEADD(MINUTE, 15, GETDATE()));
COMMIT;

SELECT user_id, full_name, avatar_url, password_hash, status
FROM users
WHERE phone_number = @phone_number AND status = 'ACTIVE';

-- Phiên đăng nhập (JWT/session) quản lý ở tầng ứng dụng; chỉ ghi vết khi là nhân viên
INSERT INTO staff_audit_logs (staff_id, action, target_table, target_id, description)
SELECT ur.user_id, 'LOGOUT', 'users', ur.user_id, N'Đăng xuất hệ thống'
FROM user_roles ur
WHERE ur.user_id = @user_id;

UPDATE users SET updated_at = GETDATE() WHERE user_id = @user_id;

UPDATE user_verifications
SET is_verified = 1
WHERE user_id = @user_id AND [type] = 'EMAIL'
  AND code = @code AND is_verified = 0 AND expires_at > GETDATE();

IF @@ROWCOUNT > 0
    UPDATE users SET status = 'ACTIVE', updated_at = GETDATE() WHERE user_id = @user_id;

DECLARE @uid INT = (SELECT user_id FROM users WHERE email = @email AND status = 'ACTIVE');

IF @uid IS NOT NULL
    INSERT INTO user_verifications (user_id, [type], code, expires_at)
    VALUES (@uid, 'RECOVERY', @recovery_code, DATEADD(MINUTE, 15, GETDATE()));

BEGIN TRAN;
DECLARE @vid INT = (
    SELECT TOP 1 v.verification_id
    FROM user_verifications v JOIN users u ON u.user_id = v.user_id
    WHERE u.email = @email AND v.[type] = 'RECOVERY' AND v.code = @recovery_code
      AND v.is_verified = 0 AND v.expires_at > GETDATE()
    ORDER BY v.verification_id DESC);

IF @vid IS NULL BEGIN ROLLBACK; THROW 50002, N'Mã không hợp lệ hoặc đã hết hạn', 1; END;

UPDATE users SET password_hash = @new_password_hash, updated_at = GETDATE() WHERE email = @email;
UPDATE user_verifications SET is_verified = 1 WHERE verification_id = @vid;
COMMIT;

-- Lấy hash cũ để ứng dụng đối chiếu
SELECT password_hash FROM users WHERE user_id = @user_id;

-- Sau khi đối chiếu đúng mật khẩu cũ
UPDATE users
SET password_hash = @new_password_hash, updated_at = GETDATE()
WHERE user_id = @user_id;

SELECT user_id, email, phone_number, full_name, avatar_url, status, created_at, updated_at
FROM users
WHERE user_id = @user_id;

UPDATE users
SET avatar_url = @avatar_url, updated_at = GETDATE()
WHERE user_id = @user_id;

BEGIN TRAN;
IF @is_default = 1
    UPDATE shipping_addresses SET is_default = 0 WHERE user_id = @user_id;

INSERT INTO shipping_addresses (user_id, recipient_name, phone, province, district, ward, detailed_address, is_default)
VALUES (@user_id, @recipient_name, @phone, @province, @district, @ward, @detailed_address, @is_default);
COMMIT;

UPDATE shipping_addresses
SET is_default = CASE WHEN address_id = @address_id THEN 1 ELSE 0 END
WHERE user_id = @user_id;

-- Schema chỉ có orders.shipping_fee (chưa có bảng phí theo khu vực). Đề xuất bổ sung:
-- CREATE TABLE shipping_zones (zone_id INT IDENTITY(1,1) PRIMARY KEY, province NVARCHAR(100) NOT NULL UNIQUE,
--     base_fee DECIMAL(18,2) NOT NULL, free_ship_threshold DECIMAL(18,2) NULL, is_active BIT DEFAULT 1);
SELECT zone_id, province, base_fee, free_ship_threshold, is_active FROM shipping_zones;
INSERT INTO shipping_zones (province, base_fee, free_ship_threshold) VALUES (@province, @base_fee, @free_ship_threshold);
UPDATE shipping_zones SET base_fee = @base_fee, free_ship_threshold = @free_ship_threshold WHERE zone_id = @zone_id;
DELETE FROM shipping_zones WHERE zone_id = @zone_id;

-- Dùng dữ liệu hiện có: phí ship đã áp theo từng tỉnh
SELECT sa.province, AVG(o.shipping_fee) AS phi_ship_trung_binh, COUNT(*) AS so_don
FROM orders o
JOIN shipping_addresses sa ON sa.user_id = o.user_id AND sa.is_default = 1
GROUP BY sa.province;

-- Flash Sale dùng running_shoes.sale_price (schema chưa có bảng thời gian Flash Sale)
-- Xem giày đang sale
SELECT shoe_id, shoe_code, shoe_name, base_price, sale_price,
       CAST((base_price - sale_price) * 100.0 / base_price AS DECIMAL(5,2)) AS ty_le_giam
FROM running_shoes
WHERE sale_price IS NOT NULL AND sale_price < base_price AND status = 'ACTIVE';

-- Tạo / cập nhật giá sale
UPDATE running_shoes SET sale_price = @sale_price WHERE shoe_id = @shoe_id AND @sale_price < base_price;

-- Kết thúc sale
UPDATE running_shoes SET sale_price = NULL WHERE shoe_id = @shoe_id;

-- Thêm vào yêu thích
IF NOT EXISTS (SELECT 1 FROM user_wishlists WHERE user_id = @user_id AND shoe_id = @shoe_id)
    INSERT INTO user_wishlists (user_id, shoe_id) VALUES (@user_id, @shoe_id);

-- Bỏ yêu thích
DELETE FROM user_wishlists WHERE user_id = @user_id AND shoe_id = @shoe_id;

-- Thống kê giày được yêu thích nhiều nhất
SELECT TOP 10 rs.shoe_id, rs.shoe_name, COUNT(*) AS so_luot_thich
FROM user_wishlists w JOIN running_shoes rs ON rs.shoe_id = w.shoe_id
GROUP BY rs.shoe_id, rs.shoe_name
ORDER BY so_luot_thich DESC;

-- Danh sách & lọc đơn
SELECT o.order_id, o.order_code, u.full_name, o.recipient_name, o.recipient_phone,
       o.final_amount, o.order_status, p.payment_method, p.payment_status, o.created_at
FROM orders o
JOIN users u        ON u.user_id = o.user_id
LEFT JOIN payments p ON p.order_id = o.order_id
WHERE (@status IS NULL OR o.order_status = @status)
  AND (@from_date IS NULL OR o.created_at >= @from_date)
  AND (@to_date   IS NULL OR o.created_at <  DATEADD(DAY, 1, @to_date))
ORDER BY o.created_at DESC;

-- Đổi trạng thái đơn + ghi lịch sử
BEGIN TRAN;
DECLARE @old_status NVARCHAR(30) = (SELECT order_status FROM orders WHERE order_id = @order_id);
UPDATE orders SET order_status = @new_status WHERE order_id = @order_id;
INSERT INTO order_status_logs (order_id, old_status, new_status, note, changed_by)
VALUES (@order_id, @old_status, @new_status, @note, @staff_id);
COMMIT;

-- Thương hiệu
SELECT brand_id, brand_name, logo_url, country FROM brands;
INSERT INTO brands (brand_name, logo_url, country) VALUES (@brand_name, @logo_url, @country);
UPDATE brands SET brand_name = @brand_name, logo_url = @logo_url, country = @country WHERE brand_id = @brand_id;
DELETE FROM brands WHERE brand_id = @brand_id
  AND NOT EXISTS (SELECT 1 FROM running_shoes WHERE brand_id = @brand_id);

-- Dòng sản phẩm (danh mục)
SELECT ps.series_id, b.brand_name, ps.series_name, ps.description
FROM product_series ps JOIN brands b ON b.brand_id = ps.brand_id;
INSERT INTO product_series (brand_id, series_name, description) VALUES (@brand_id, @series_name, @description);
UPDATE product_series SET series_name = @series_name, description = @description WHERE series_id = @series_id;
DELETE FROM product_series WHERE series_id = @series_id
  AND NOT EXISTS (SELECT 1 FROM running_shoes WHERE series_id = @series_id);

SELECT size_id, size_eu, size_us, size_cm FROM size_charts ORDER BY size_eu;
INSERT INTO size_charts (size_eu, size_us, size_cm) VALUES (@size_eu, @size_us, @size_cm);
UPDATE size_charts SET size_eu = @size_eu, size_us = @size_us, size_cm = @size_cm WHERE size_id = @size_id;
DELETE FROM size_charts WHERE size_id = @size_id
  AND NOT EXISTS (SELECT 1 FROM shoe_variants WHERE size_id = @size_id);

-- Gợi ý size theo chiều dài bàn chân (mm), chừa ~10mm
SELECT TOP 1 size_id, size_eu, size_us, size_cm
FROM size_charts
WHERE size_cm * 10 >= @foot_length_mm + 10
ORDER BY size_cm;

-- Schema chưa có bảng chat; dùng customer_complaints làm kênh liên hệ/hỗ trợ
SELECT c.complaint_id, u.full_name, u.phone_number, c.complaint_type, c.content, c.status, c.created_at
FROM customer_complaints c JOIN users u ON u.user_id = c.user_id
WHERE (@status IS NULL OR c.status = @status)
ORDER BY c.created_at DESC;

INSERT INTO customer_complaints (user_id, shoe_id, order_id, complaint_type, content)
VALUES (@user_id, @shoe_id, @order_id, @complaint_type, @content);

UPDATE customer_complaints SET status = @status WHERE complaint_id = @complaint_id;

SELECT coupon_id, code, discount_type, discount_value, min_order_value, start_date, end_date, usage_limit
FROM coupons ORDER BY end_date DESC;

INSERT INTO coupons (code, discount_type, discount_value, min_order_value, start_date, end_date, usage_limit)
VALUES (@code, @discount_type, @discount_value, @min_order_value, @start_date, @end_date, @usage_limit);

UPDATE coupons SET discount_value = @discount_value, min_order_value = @min_order_value,
       start_date = @start_date, end_date = @end_date, usage_limit = @usage_limit
WHERE coupon_id = @coupon_id;

DELETE FROM coupons WHERE coupon_id = @coupon_id;

-- Kiểm tra mã hợp lệ khi áp dụng
SELECT coupon_id, discount_type, discount_value
FROM coupons
WHERE code = @code AND GETDATE() BETWEEN start_date AND end_date
  AND min_order_value <= @subtotal AND usage_limit > 0;

-- Ảnh theo biến thể giày
SELECT v.variant_id, rs.shoe_name, c.color_name, v.sku, v.image_url
FROM shoe_variants v
JOIN running_shoes rs ON rs.shoe_id = v.shoe_id
JOIN shoe_colors c    ON c.color_id = v.color_id
WHERE v.shoe_id = @shoe_id;

UPDATE shoe_variants SET image_url = @image_url WHERE variant_id = @variant_id;

-- Ảnh đính kèm đánh giá
SELECT m.media_id, m.media_url, r.review_id, rs.shoe_name
FROM review_media m
JOIN shoe_reviews r   ON r.review_id = m.review_id
JOIN running_shoes rs ON rs.shoe_id = r.shoe_id;
INSERT INTO review_media (review_id, media_url) VALUES (@review_id, @media_url);
DELETE FROM review_media WHERE media_id = @media_id;

-- Schema chưa có bảng đơn vị vận chuyển/phí; truy vấn trên orders.shipping_fee
SELECT order_id, order_code, shipping_fee, order_status FROM orders
WHERE (@status IS NULL OR order_status = @status);

UPDATE orders SET shipping_fee = @shipping_fee, final_amount = subtotal_amount - ISNULL(discount_amount, 0) + @shipping_fee
WHERE order_id = @order_id AND order_status IN ('PENDING', 'CONFIRMED');

-- Thống kê tổng phí ship
SELECT CAST(created_at AS DATE) AS ngay, COUNT(*) AS so_don, SUM(shipping_fee) AS tong_phi_ship
FROM orders GROUP BY CAST(created_at AS DATE) ORDER BY ngay;

-- Hủy đơn
BEGIN TRAN;
DECLARE @old NVARCHAR(30) = (SELECT order_status FROM orders WHERE order_id = @order_id);
UPDATE orders SET order_status = 'CANCELLED' WHERE order_id = @order_id AND order_status IN ('PENDING', 'CONFIRMED');
IF @@ROWCOUNT > 0
    INSERT INTO order_status_logs (order_id, old_status, new_status, note, changed_by)
    VALUES (@order_id, @old, 'CANCELLED', @note, @staff_id);
COMMIT;

-- Danh sách yêu cầu trả hàng
SELECT r.return_id, o.order_code, u.full_name, r.reason, r.refund_amount, r.status, r.created_at
FROM order_returns r
JOIN orders o ON o.order_id = r.order_id
JOIN users u  ON u.user_id = r.user_id
WHERE (@status IS NULL OR r.status = @status);

-- Duyệt / từ chối
UPDATE order_returns SET status = @status, refund_amount = @refund_amount WHERE return_id = @return_id;

-- Ghi nhận hoàn tiền
BEGIN TRAN;
INSERT INTO refund_transactions (return_id, amount, gateway_transaction_id)
VALUES (@return_id, @amount, @gateway_transaction_id);
UPDATE order_returns SET status = 'REFUNDED' WHERE return_id = @return_id;
COMMIT;

-- Banner
SELECT banner_id, title, image_url, target_url, display_order, is_active FROM cms_banners ORDER BY display_order;
INSERT INTO cms_banners (title, image_url, target_url, display_order) VALUES (@title, @image_url, @target_url, @display_order);
UPDATE cms_banners SET title = @title, image_url = @image_url, target_url = @target_url,
       display_order = @display_order, is_active = @is_active WHERE banner_id = @banner_id;
DELETE FROM cms_banners WHERE banner_id = @banner_id;

-- Trang nội dung (bài viết & hướng dẫn)
SELECT article_id, title, slug, category, created_at FROM running_articles ORDER BY created_at DESC;
UPDATE running_articles SET title = @title, content = @content, category = @category WHERE article_id = @article_id;
UPDATE guidance_contents SET title = @title, content_html = @content_html, updated_at = GETDATE()
WHERE guide_type = @guide_type;

-- Sao lưu đầy đủ
BACKUP DATABASE [BeginnerRunningShoesDB]
TO DISK = N'D:\Backup\BeginnerRunningShoesDB_Full.bak' WITH INIT, COMPRESSION, STATS = 10;

-- Sao lưu chênh lệch
BACKUP DATABASE [BeginnerRunningShoesDB]
TO DISK = N'D:\Backup\BeginnerRunningShoesDB_Diff.bak' WITH DIFFERENTIAL, COMPRESSION;

-- Phục hồi
USE master;
ALTER DATABASE [BeginnerRunningShoesDB] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
RESTORE DATABASE [BeginnerRunningShoesDB]
FROM DISK = N'D:\Backup\BeginnerRunningShoesDB_Full.bak' WITH REPLACE;
ALTER DATABASE [BeginnerRunningShoesDB] SET MULTI_USER;

-- Khách hủy đơn nhiều lần trong 30 ngày
SELECT user_id, COUNT(*) AS so_don_huy
FROM orders WHERE order_status = 'CANCELLED' AND created_at >= DATEADD(DAY, -30, GETDATE())
GROUP BY user_id HAVING COUNT(*) >= 3;

-- Một số điện thoại nhận hàng dùng bởi nhiều tài khoản
SELECT recipient_phone, COUNT(DISTINCT user_id) AS so_tai_khoan
FROM orders GROUP BY recipient_phone HAVING COUNT(DISTINCT user_id) >= 3;

-- Đơn giá trị lớn thanh toán thất bại
SELECT o.order_code, o.final_amount, p.payment_status
FROM orders o JOIN payments p ON p.order_id = o.order_id
WHERE p.payment_status = 'FAILED' AND o.final_amount >= 10000000;

-- Khóa tài khoản nghi vấn
UPDATE users SET status = 'LOCKED', updated_at = GETDATE() WHERE user_id = @user_id;

SELECT guide_type, title, content_html, updated_at
FROM guidance_contents
WHERE guide_type = 'HOW_TO_DETERMINE_ARCH';

SELECT guide_type, title, content_html, updated_at
FROM guidance_contents
WHERE guide_type = 'HOW_TO_DETERMINE_ARCH';

SELECT guide_type, title, content_html, updated_at
FROM guidance_contents
WHERE guide_type = 'HOW_TO_MEASURE_FOOT';

